<?php
declare(strict_types=1);require __DIR__.'/bootstrap.php';$error='';$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$action=$_POST['action']??'';if($action==='save'){$id=(int)($_POST['id']??0);$title=trim((string)($_POST['title']??''));$slug=slugify((string)($_POST['slug']?:$title));$price=trim((string)($_POST['price']??''));$price=$price===''?null:(float)$price;if($title==='')throw new RuntimeException('Xidmət adı mütləqdir.');if($price!==null&&$price<0)throw new RuntimeException('Qiymət mənfi ola bilməz.');$args=[$title,$slug,trim((string)($_POST['short_description']??'')),trim((string)($_POST['description']??'')),$price,substr(strtoupper((string)($_POST['currency']??'AZN')),0,3),trim((string)($_POST['price_label']??'')),(int)($_POST['sort_order']??0),isset($_POST['is_active'])?1:0];if($id){$q=$pdo->prepare('UPDATE services SET title=?,slug=?,short_description=?,description=?,price=?,currency=?,price_label=?,sort_order=?,is_active=? WHERE id=?');$q->execute([...$args,$id]);}else{$q=$pdo->prepare('INSERT INTO services(title,slug,short_description,description,price,currency,price_label,sort_order,is_active) VALUES(?,?,?,?,?,?,?,?,?)');$q->execute($args);}$success='Xidmət yadda saxlanıldı.';}elseif($action==='delete'){$q=$pdo->prepare('DELETE FROM services WHERE id=?');$q->execute([(int)$_POST['id']]);$success='Xidmət silindi.';}}catch(Throwable $x){$error=$x instanceof PDOException?'Slug təkrarlanır və ya məlumat bazası xətası.':$x->getMessage();}}
$edit=null;if(isset($_GET['edit'])){$q=$pdo->prepare('SELECT * FROM services WHERE id=?');$q->execute([(int)$_GET['edit']]);$edit=$q->fetch()?:null;}$rows=$pdo->query('SELECT * FROM services ORDER BY sort_order,id DESC')->fetchAll();admin_header('Xidmətlər','services');?>
<?php if($error):?><div class="notice error"><?=e($error)?></div><?php endif;?><?php if($success):?><div class="notice success"><?=e($success)?></div><?php endif;?>
<div class="content-grid"><section class="panel"><h2><?= $edit?'Xidməti redaktə et':'Yeni xidmət' ?></h2><form class="admin-form" method="post"><?=csrf_field()?><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?=e((string)($edit['id']??0))?>"><label>Xidmət adı<input name="title" required maxlength="220" value="<?=e($edit['title']??'')?>"></label><label>Slug<input name="slug" value="<?=e($edit['slug']??'')?>" placeholder="avtomatik"></label><label>Qısa təsvir<input name="short_description" maxlength="500" value="<?=e($edit['short_description']??'')?>"></label><label>Ətraflı təsvir<textarea name="description" rows="5"><?=e($edit['description']??'')?></textarea></label><div class="form-row"><label>Qiymət<input type="number" step=".01" min="0" name="price" value="<?=e((string)($edit['price']??''))?>"></label><label>Valyuta<input name="currency" maxlength="3" value="<?=e($edit['currency']??'AZN')?>"></label></div><label>Qiymət qeydi<input name="price_label" maxlength="120" value="<?=e($edit['price_label']??'')?>" placeholder="Fərdi təklif / ayda"></label><label>Sıralama<input type="number" name="sort_order" value="<?=e((string)($edit['sort_order']??0))?>"></label><label class="check-label"><input type="checkbox" name="is_active" <?=(!$edit||!empty($edit['is_active']))?'checked':''?>> Aktiv</label><div class="form-actions"><button class="btn-admin">Yadda saxla</button><?php if($edit):?><a class="btn-secondary" href="services.php">Ləğv et</a><?php endif;?></div></form></section>
<section class="panel"><h2>Xidmət siyahısı</h2><div class="table-wrap"><table><thead><tr><th>Xidmət</th><th>Qiymət</th><th>Status</th><th>Əməliyyat</th></tr></thead><tbody><?php foreach($rows as $s):?><tr><td><b><?=e($s['title'])?></b><small class="subline"><?=e($s['slug'])?></small></td><td><?=$s['price']!==null?e(number_format((float)$s['price'],2).' '.$s['currency']):e($s['price_label']?:'Fərdi təklif')?></td><td><?=$s['is_active']?'Aktiv':'Passiv'?></td><td class="actions"><a href="?edit=<?=$s['id']?>">Redaktə</a><form method="post" onsubmit="return confirm('Xidmət silinsin?')"><?=csrf_field()?><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?=$s['id']?>"><button class="link-danger">Sil</button></form></td></tr><?php endforeach;?></tbody></table></div></section></div><?php admin_footer();?>